import sys
from typing import List

def solve(n: int, X: int, prices: List[int]) -> int:
    prices.sort()
    count = 0
    i = 0
    while i < n - 1:
        if prices[i] + prices[i + 1] <= X:
            count += 2
            i += 2
        else:
            count += 1
            i += 1
    if i < n:
        count += 1
    return count

def main():
    n, X = map(int, input().split())
    prices = list(map(int, input().split()))
    result = solve(n, X, prices)
    print(result)

if __name__ == "__main__":
    main()

def solve():
    n, X = map(int, input().split())
    prices = list(map(int, input().split()))

    prices.sort(reverse=True)

    count = 0
    for i in range(n - 1):
        if prices[i] >= X:
            count += 1
        else:
            break

    if count % 2 == 1:
        count -= 1

    print(count)

